   428→import { useState, useEffect, useMemo, useCallback } from 'react';
   429→import type { Lieferanten, Bestellungen, Produkte, Lagerbestand, Wareneingang } from '@/types/app';
   430→import { LivingAppsService } from '@/services/livingAppsService';
   431→
   432→export function useDashboardData() {
   433→  const [lieferanten, setLieferanten] = useState<Lieferanten[]>([]);
   434→  const [bestellungen, setBestellungen] = useState<Bestellungen[]>([]);
   435→  const [produkte, setProdukte] = useState<Produkte[]>([]);
   436→  const [lagerbestand, setLagerbestand] = useState<Lagerbestand[]>([]);
   437→  const [wareneingang, setWareneingang] = useState<Wareneingang[]>([]);
   438→  const [loading, setLoading] = useState(true);
   439→  const [error, setError] = useState<Error | null>(null);
   440→
   441→  const fetchAll = useCallback(async () => {
   442→    setError(null);
   443→    try {
   444→      const [lieferantenData, bestellungenData, produkteData, lagerbestandData, wareneingangData] = await Promise.all([
   445→        LivingAppsService.getLieferanten(),
   446→        LivingAppsService.getBestellungen(),
   447→        LivingAppsService.getProdukte(),
   448→        LivingAppsService.getLagerbestand(),
   449→        LivingAppsService.getWareneingang(),
   450→      ]);
   451→      setLieferanten(lieferantenData);
   452→      setBestellungen(bestellungenData);
   453→      setProdukte(produkteData);
   454→      setLagerbestand(lagerbestandData);
   455→      setWareneingang(wareneingangData);
   456→    } catch (err) {
   457→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   458→    } finally {
   459→      setLoading(false);
   460→    }
   461→  }, []);
   462→
   463→  useEffect(() => { fetchAll(); }, [fetchAll]);
   464→
   465→  const lieferantenMap = useMemo(() => {
   466→    const m = new Map<string, Lieferanten>();
   467→    lieferanten.forEach(r => m.set(r.record_id, r));
   468→    return m;
   469→  }, [lieferanten]);
   470→
   471→  const bestellungenMap = useMemo(() => {
   472→    const m = new Map<string, Bestellungen>();
   473→    bestellungen.forEach(r => m.set(r.record_id, r));
   474→    return m;
   475→  }, [bestellungen]);
   476→
   477→  const produkteMap = useMemo(() => {
   478→    const m = new Map<string, Produkte>();
   479→    produkte.forEach(r => m.set(r.record_id, r));
   480→    return m;
