   503→          </DialogFooter>
   504→        </DialogContent>
   505→      </Dialog>
   506→
   507→      {/* ── Delete Confirm ─────────────────────────────────────────────────── */}
   508→      <Dialog open={!!deleteTarget} onOpenChange={open => !open && setDeleteTarget(null)}>
