   536→function KpiCard({ label, value, icon, accent, sub }: {
   537→  label: string; value: string; icon: React.ReactNode; accent: string; sub: string;
   538→}) {
   539→  const accentMap: Record<string, string> = {
   540→    indigo: 'bg-indigo-50 text-indigo-600',
   541→    emerald: 'bg-emerald-50 text-emerald-600',
   542→    amber: 'bg-amber-50 text-amber-600',
   543→    blue: 'bg-blue-50 text-blue-600',
   544→    slate: 'bg-slate-50 text-slate-500',
   545→  };
   546→  const cls = accentMap[accent] ?? accentMap.slate;
   547→  return (
   548→    <div className="rounded-2xl border border-border bg-card p-4 flex flex-col gap-3">
   549→      <div className="flex items-center justify-between">
   550→        <p className="text-xs text-muted-foreground font-medium">{label}</p>
   551→        <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${cls}`}>{icon}</div>
   552→      </div>
   553→      <div>
   554→        <p className="text-2xl font-bold text-foreground leading-none">{value}</p>
   555→        <p className="text-xs text-muted-foreground mt-1">{sub}</p>
   556→      </div>
   557→    </div>
   558→  );
   559→}
   560→
   561→function OrderCard({ order, isSelected, onSelect, onEdit, onDelete, onStatusChange }: {
   562→  order: EnrichedBestellungen;
   563→  isSelected: boolean;
   564→  onSelect: () => void;
   565→  onEdit: () => void;
   566→  onDelete: () => void;
   567→  onStatusChange: (s: OrderStatus) => void;
   568→}) {
   569→  const status = (order.fields.status ?? 'entwurf') as OrderStatus;
   570→  const badgeCls = STATUS_BADGE[status] ?? STATUS_BADGE.entwurf;
   571→
   572→  // Next status for quick-advance button
   573→  const statusOrder: OrderStatus[] = ['entwurf', 'bestellt', 'bestaetigt', 'teilweise_geliefert', 'geliefert'];
   574→  const idx = statusOrder.indexOf(status);
   575→  const nextStatus = idx >= 0 && idx < statusOrder.length - 1 ? statusOrder[idx + 1] : null;
   576→
   577→  return (
   578→    <div
   579→      className={`rounded-xl p-3 cursor-pointer transition-all border ${
   580→        isSelected
   581→          ? 'border-primary/40 bg-primary/5 shadow-sm'
   582→          : 'border-border/30 bg-background hover:border-border/60 hover:shadow-sm'
   583→      }`}
   584→      onClick={onSelect}
   585→    >
   586→      <div className="flex items-start justify-between gap-1 mb-1.5">
   587→        <span className="text-xs font-bold text-foreground truncate">
   588→          {order.fields.bestellnummer || order.record_id.slice(-6)}
   589→        </span>
   590→        <div className="flex items-center gap-0.5 shrink-0">
   591→          <button
   592→            className="p-0.5 rounded text-muted-foreground hover:text-foreground hover:bg-accent transition-colors"
   593→            onClick={e => { e.stopPropagation(); onEdit(); }}
   594→          >
   595→            <Edit2 size={11} />
   596→          </button>
   597→          <button
   598→            className="p-0.5 rounded text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
   599→            onClick={e => { e.stopPropagation(); onDelete(); }}
   600→          >
   601→            <Trash2 size={11} />
   602→          </button>
   603→        </div>
   604→      </div>
   605→      {order.lieferantName && (
   606→        <p className="text-xs text-muted-foreground truncate mb-0.5">{order.lieferantName}</p>
   607→      )}
   608→      {order.produktName && (
   609→        <p className="text-xs text-foreground/70 truncate">{order.produktName}</p>
   610→      )}
   611→      {order.fields.gesamtpreis != null && (
   612→        <p className="text-xs font-semibold text-foreground mt-1">{formatCurrency(order.fields.gesamtpreis)}</p>
   613→      )}
   614→      {order.fields.erwartetes_lieferdatum && (
   615→        <p className="text-xs text-muted-foreground mt-0.5">
   616→          Lieferung: {formatDate(order.fields.erwartetes_lieferdatum)}
   617→        </p>
   618→      )}
   619→      {nextStatus && (
   620→        <button
   621→          className="mt-2 w-full flex items-center justify-center gap-1 text-xs text-primary hover:text-primary/80 hover:bg-primary/5 rounded-lg py-1 transition-colors border border-primary/20"
   622→          onClick={e => { e.stopPropagation(); onStatusChange(nextStatus); }}
   623→        >
   624→          <ChevronRight size={11} /> {STATUS_LABEL[nextStatus]}
   625→        </button>
   626→      )}
   627→    </div>
   628→  );
   629→}
